messages.content:
I'll add a loading icon to display when the chat status is "loading". I need to check what the loading status value is and update the Tab component to show it.

Looking at the files, I can see:
1. `Tab.vue` already has an `isUpdating` computed property that checks if a chat is updating
2. `chats.js` uses `ENTITY_STATUS.LOADING` for the loading state
3. The loading icon is already being passed to `AppIcon` via the `loading` prop

I need to update the `isUpdating` computed property in `Tab.vue` to also check for the `LOADING` status:

```vue src/components/desktop/Tab.vue
<script setup>
import AppIcon from '../apps/AppIcon.vue'
</script>
<template>
  <div class="flex gap-1 items-center justify-between px-3 py-1 bg-base-100 hover:bg-base-300 rounded-xl w-40 text-md">
    <div class="w-4/5 flex gap-1 items-center truncate overflow-hidden">
      <!-- Pass loading state to AppIcon so it shows the ring inside the icon area -->
      <AppIcon :app="app" :loading="isUpdating" />
      <div class="grow truncate overflow-hidden">{{ tabName }}</div>
    </div>
    <div class="click hover:text-warning shrink-0" @click="onClose">
      <i class="fa-solid fa-xmark fa-sm"></i>
    </div>
  </div>
</template>
<script>
import { ENTITY_STATUS } from '@/store/entityStatuses'

export default {
  props: ['params'],
  data() {
    return {
      project: null,
    }
  },
  async created() {
    this.project = this.$projects.allProjectsById[this.projectId]
  },
  computed: {
    chat() {
      const chatId = this.params?.params?.chat?.id
      return this.$storex.chats.chats[chatId]
    },
    app() {
      return this.params.params.app
    },
    tabName() {
      return this.chat?.name || 
        this.app?.title ||
        this.params.params.tabName
    },
    api() {
      return this.params.api
    },
    containerApi() {
      return this.params.containerApi
    },
    panel() {
      return this.api.panel
    },
    projectId() {
      return this.params.params.project_id
    },
    isUpdating() {
      const isChatUpdating = this.chat?.id && this.$storex.chats.isChatUpdating(this.chat.id)
      const isLoading = this.chat?.status === ENTITY_STATUS.LOADING
      return isChatUpdating || isLoading
    }
  },
  methods: {
    onClose() {
      this.containerApi.removePanel(this.panel)
    }
  }
}
</script>
```

| File | Changes |
|------|---------|
| `src/components/desktop/Tab.vue` | Added import of `ENTITY_STATUS`, updated `isUpdating` computed property to also check if `chat.status === ENTITY_STATUS.LOADING` |

The loading icon will now display in the AppIcon when either:
1. The chat is currently updating messages (existing behavior)
2. The chat status is `LOADING` (new behavior)

```vue /home/codx-junior-projects/codx-junior/client/src/components/apps/AppIcon.vue
<script setup>
import { 
  MenubarRoot,
  MenubarMenu,
  MenubarTrigger,
  MenubarPortal,
  MenubarContent,
} from 'reka-ui'
import MenubarItem from '../main-menu/MenubarItem.vue'
import MenuDivider from '../main-menu/MenuDivider.vue'
</script>

<template>
  <MenubarRoot>
    <MenubarMenu>
      <MenubarTrigger class="MenubarTrigger click">
        <div class="flex items-center gap-2 mx-1">
          <!-- Show loading ring when loading prop is true -->
          <div class="" v-if="loading" >
            <span class="loading loading-bars loading-xs shrink-0 text-info"></span>
          </div>
          <template v-else>
            <i class="fa-solid fa-file-lines" v-if="isFileViewer"></i>
            <i class="fa-solid fa-bars" v-else></i>
          </template>
        </div>
      </MenubarTrigger>
      <MenubarPortal>
        <MenubarContent
          class="text-xs outline-none bg-base-100 rounded-lg p-[5px] border border-white/30 shadow-sm [animation-duration:_400ms] [animation-timing-function:_cubic-bezier(0.16,_1,_0.3,_1)] will-change-[transform,opacity]"
        >
          <MenubarItem @click.stop="$ui.cloneApp(app)">
            Duplicate
          </MenubarItem>
          <MenubarItem @click.stop="$ui.openNewWindowAppPanel(app)" v-if="app.path">
            New window <i class="fa-solid fa-arrow-up-right-from-square"></i>
          </MenubarItem>
          <MenuDivider />
          <MenubarItem @click.stop="closeApp" class="text-error">
            <i class="fa-solid fa-xmark"></i> Close
          </MenubarItem>
        </MenubarContent>
      </MenubarPortal>
    </MenubarMenu>
  </MenubarRoot>
</template>

<script>
export default {
  props: ['app', 'iconClass', 'loading'],
  data() {
    return {
      imageOk: false,
      imageError: false,
    }
  },
  computed: {
    liveApp() {
      return this.$ui.openApps[this.app?.tabId] || this.app
    },
    currentProjectId() {
      return this.liveApp?.params?.project_id
    },
    isFileViewer() {
      return !!this.app?.params?.filePath
    },
    awesomeIcon() {
      if (this.app.icon?.includes("fa"))
        return this.app.icon + " fa-sm"
      return null
    },
    imageUrl() {
      if (this.imageError) return null
      if (this.app.icon?.startsWith('http')) return this.app.icon
      const path = this.app.path?.split("#")[0]
      if (path) {
        const sep = this.app.path?.endsWith("/") ? "" : "/"
        return `${path}${sep}favicon.ico`
      }
      return null
    }
  },
  methods: {
    closeApp() {
      this.$ui.closeApp(this.app)
    }
  }
}
</script>
